def mlfq(procs, levels=3, base_q=2, aging_threshold=8):
    """多级反馈队列：新进程进最高级；用完时间片未完成则降级；等待过久则升级（老化）"""
    queues = [[] for _ in range(levels)]   # 每级存 (pid, 已等待时长)
    remaining = {p[0]: p[2] for p in procs}
    arrive = {p[0]: p[1] for p in procs}
    level_of = {}
    waited = {p[0]: 0 for p in procs}
    finish = {}
    first_run = {}
    now = 0
    pending = sorted(procs, key=lambda x: x[1])
    idx = 0
    log = []

    while len(finish) < len(procs):
        while idx < len(pending) and pending[idx][1] <= now:
            p = pending[idx][0]
            queues[0].append(p)
            level_of[p] = 0
            idx += 1
        # 老化：等待过久的进程升级
        for lv in range(levels - 1, 0, -1):
            for p in list(queues[lv]):
                if waited[p] >= aging_threshold:
                    queues[lv].remove(p)
                    queues[lv - 1].append(p)
                    level_of[p] = lv - 1
                    waited[p] = 0
                    log.append("t=%d %s 老化升级 -> Q%d" % (now, p, lv - 1))
        cur_lv = -1
        for lv in range(levels):
            if queues[lv]:
                cur_lv = lv
                break
        if cur_lv < 0:
            now += 1
            for p in remaining:
                if p not in finish and arrive[p] <= now:
                    waited[p] += 1
            continue
        pid = queues[cur_lv].pop(0)
        q = base_q * (2 ** cur_lv)          # 时间片逐级倍增
        if pid not in first_run:
            first_run[pid] = now
        run = min(q, remaining[pid])
        now += run
        remaining[pid] -= run
        for p in remaining:
            if p not in finish and p != pid and arrive[p] <= now:
                waited[p] += run
        while idx < len(pending) and pending[idx][1] <= now:
            p = pending[idx][0]
            queues[0].append(p)
            level_of[p] = 0
            idx += 1
        if remaining[pid] > 0:
            nlv = min(cur_lv + 1, levels - 1)
            queues[nlv].append(pid)
            level_of[pid] = nlv
            log.append("t=%d %s 用完 Q%d 的时间片 %d -> 降到 Q%d" % (now, pid, cur_lv, q, nlv))
        else:
            finish[pid] = now
            log.append("t=%d %s 完成" % (now, pid))
    return log, first_run, finish


procs = [("P1", 0, 9), ("P2", 0, 3), ("P3", 4, 5), ("P4", 6, 2)]
log, fr, fin = mlfq(procs)
print("进程(A=到达, S=服务): " + ", ".join("%s(A=%d,S=%d)" % (p[0], p[1], p[2]) for p in procs))
print("队列: Q0(q=2) > Q1(q=4) > Q2(q=8)，等待 >= 8 触发老化升级")
print("")
print("--- 调度日志 ---")
for line in log:
    print("  " + line)
print("")
print("%-4s %-8s %-8s %-10s" % ("进程", "首次执行", "完成", "周转"))
for pid in sorted(fin):
    a = [p[1] for p in procs if p[0] == pid][0]
    print("%-4s %-8d %-8d %-10d" % (pid, fr[pid], fin[pid], fin[pid] - a))
print("")
print("特点: 交互式短作业留在高优先级（响应快），长作业逐级下沉用大时间片跑完（周转可接受）")
